function normalizeEvolutionLocales(key: string, values: string[]) {
  const override = EVOLUTION_13_OVERRIDES[key];
  if (override) {
    return override;
  }
  if (values.length >= 13) {
    return values;
  }

  const [en = "", zh = en, zhTW = zh] = values;
  return [
    en,
    zh,
    zhTW,
    values[3] ?? en,
    values[4] ?? en,
    values[5] ?? en,
    values[6] ?? en,
    values[7] ?? en,
    values[8] ?? en,
    values[9] ?? en,
    values[10] ?? en,
    values[11] ?? en,
    values[12] ?? en,
  ];
}

export const EVOLUTION_RUNTIME_DICT: Record<string, string[]> = {
  ...Object.fromEntries(
    Object.entries(EVOLUTION_RUNTIME_RAW_DICT).map(([key, values]) => [key, normalizeEvolutionLocales(key, values)]),
  ),
  ...EVOLUTION_13_OVERRIDES,
};

const EVOLUTION_LANG_INDICES: Record<string, number> = {
  en: 0,
  zh: 1,
  "zh-TW": 2,
  es: 3,
  fr: 4,
  de: 5,
  ja: 6,
  ko: 7,
  ru: 8,
  pt: 9,
  it: 10,
  ar: 11,
  hi: 12,
};

export function translateEvolutionCopy(
  lang: string,
  key: string,
  ...args: (string | number)[]
) {
  const idx = EVOLUTION_LANG_INDICES[lang] ?? 0;
  let str = EVOLUTION_RUNTIME_DICT[key]?.[idx];
  if (!str && str !== "") {
    str = EVOLUTION_RUNTIME_DICT[key]?.[0] ?? key;
  }
  args.forEach((arg, i) => {
    str = str.replace(`{${i}}`, String(arg));
  });
  return str;
}
